alter table public.applications add column questions_version uuid not null default gen_random_uuid();
alter table public.application_approvals add column questions_version uuid;
create table public.application_questions (id uuid primary key default gen_random_uuid(), application_id uuid not null references public.applications(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, question text not null check(length(trim(question)) between 3 and 2000), answer text not null default '' check(length(answer)<=6000), sensitive boolean not null default true, confirmed boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(not confirmed or length(trim(answer))>0));
create index application_questions_app_idx on public.application_questions(application_id,created_at);
alter table public.application_questions enable row level security;
create policy questions_read on public.application_questions for select to authenticated using(user_id=(select auth.uid()));
create policy questions_insert on public.application_questions for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.applications a where a.id=application_id and a.user_id=(select auth.uid())));
create policy questions_update on public.application_questions for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()) and exists(select 1 from public.applications a where a.id=application_id and a.user_id=(select auth.uid())));
create policy questions_delete on public.application_questions for delete to authenticated using(user_id=(select auth.uid()));
grant select,insert,update,delete on public.application_questions to authenticated;
create table public.reusable_answers (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, question text not null check(length(trim(question)) between 3 and 2000), answer text not null check(length(trim(answer)) between 1 and 6000), sensitive boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index reusable_answers_user_idx on public.reusable_answers(user_id,updated_at desc);
alter table public.reusable_answers enable row level security;
create policy reusable_select on public.reusable_answers for select to authenticated using(user_id=(select auth.uid()));
create policy reusable_insert on public.reusable_answers for insert to authenticated with check(user_id=(select auth.uid()));
create policy reusable_update on public.reusable_answers for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy reusable_delete on public.reusable_answers for delete to authenticated using(user_id=(select auth.uid()));
grant select,insert,update,delete on public.reusable_answers to authenticated;
create function public.guard_question_identity() returns trigger language plpgsql set search_path='' as $$ begin if old.application_id is distinct from new.application_id or old.user_id is distinct from new.user_id then raise exception 'Cannot move an application question'; end if; return new; end $$;
create trigger question_identity before update on public.application_questions for each row execute function public.guard_question_identity();
create function public.touch_application_questions() returns trigger language plpgsql security definer set search_path='' as $$ begin update public.applications set questions_version=gen_random_uuid(),updated_at=clock_timestamp() where id=coalesce(new.application_id,old.application_id) and user_id=coalesce(new.user_id,old.user_id); return coalesce(new,old); end $$;
create trigger question_revision after insert or update or delete on public.application_questions for each row execute function public.touch_application_questions();
create or replace function public.approve_application(p_id uuid,p_cv uuid,p_cover uuid) returns text language plpgsql security definer set search_path='' as $$ declare uid uuid:=auth.uid(); a public.applications%rowtype; latest_cv uuid; latest_cover uuid; begin if uid is null then return 'not_found'; end if; select * into a from public.applications where id=p_id and user_id=uid for update; if not found then return 'not_found'; end if; if a.status not in ('saved','preparing','review_required','action_required') or exists(select 1 from public.manual_submissions where application_id=p_id) then return 'invalid_state'; end if; if exists(select 1 from public.application_questions where application_id=p_id and user_id=uid and not confirmed) then return 'unreviewed_questions'; end if; select id into latest_cv from public.application_documents where application_id=p_id and user_id=uid and kind='cv' order by created_at desc,id desc limit 1; select id into latest_cover from public.application_documents where application_id=p_id and user_id=uid and kind='cover_letter' order by created_at desc,id desc limit 1; if p_cv is distinct from latest_cv or p_cover is distinct from latest_cover then return 'invalid_document'; end if; insert into public.application_approvals(application_id,user_id,cv_document_id,cover_document_id,questions_version) values(p_id,uid,p_cv,p_cover,a.questions_version); update public.applications set status='action_required',updated_at=now() where id=p_id; insert into public.application_events(application_id,user_id,event) values(p_id,uid,'Preparation approved for manual handoff'); return 'approved'; end $$;
create or replace function public.record_manual_application(p_id uuid,p_approval uuid,p_evidence text) returns text language plpgsql security definer set search_path='' as $$ declare uid uuid:=auth.uid(); a public.applications%rowtype; approval public.application_approvals%rowtype; latest_cv uuid; latest_cover uuid; begin if uid is null then return 'not_found'; end if; if p_evidence is null or length(trim(p_evidence)) not between 3 and 1000 then return 'invalid_evidence'; end if; select * into a from public.applications where id=p_id and user_id=uid for update; if not found then return 'not_found'; end if; if exists(select 1 from public.manual_submissions where application_id=p_id) then return 'already_recorded'; end if; select * into approval from public.application_approvals where id=p_approval and application_id=p_id and user_id=uid; if a.status<>'action_required' or not found then return 'invalid_state'; end if; select id into latest_cv from public.application_documents where application_id=p_id and user_id=uid and kind='cv' order by created_at desc,id desc limit 1; select id into latest_cover from public.application_documents where application_id=p_id and user_id=uid and kind='cover_letter' order by created_at desc,id desc limit 1; if approval.cv_document_id is distinct from latest_cv or approval.cover_document_id is distinct from latest_cover or approval.questions_version is distinct from a.questions_version then return 'approval_outdated'; end if; insert into public.manual_submissions(application_id,user_id,approval_id,evidence) values(p_id,uid,p_approval,trim(p_evidence)); update public.applications set status='applied',updated_at=now() where id=p_id; insert into public.application_events(application_id,user_id,event) values(p_id,uid,'External submission self-reported by user'); return 'recorded'; end $$;
